-- Database logic that the Postgres migrations keep in triggers, functions and views, written for SQL Server.
-- Postgres originals: the booking_denorm_* triggers and refresh_booking_time_status_* functions, the
-- membership_role_change_trigger, and the BookingTimeStatus / BookingTimeStatusDenormalized views.
-- Also the reference rows those migrations insert (feature flags, system roles and permissions,
-- out-of-office reasons, the system audit actor, the Cal Video app). Inserts skip rows that exist.
--
-- Differences from Postgres:
--   - T-SQL triggers fire once per statement, so they work on the inserted/deleted sets.
--   - There are no BEFORE triggers: the membership role trigger is AFTER INSERT/UPDATE and sets
--     customRoleId with an UPDATE (RECURSIVE_TRIGGERS is off, so it does not fire itself again).
--   - The Postgres denorm triggers swallow errors and log a warning. A T-SQL trigger can't: an error
--     inside one dooms the transaction, so here a failure rolls back the booking change.
--   - Enum columns hold the enum key names, so 'cancelled' is 'CANCELLED'.
SET NOCOUNT ON;

-- BookingDenormalized: keep in step with Booking, EventType and users
EXEC(N'CREATE OR ALTER TRIGGER [dbo].[booking_denorm_booking_insert_update_trigger] ON [dbo].[Booking] AFTER INSERT, UPDATE AS
BEGIN
  SET NOCOUNT ON;
  IF NOT EXISTS (SELECT 1 FROM inserted) RETURN;
  DELETE bd FROM "BookingDenormalized" bd INNER JOIN inserted i ON i.id = bd.id;
  INSERT INTO "BookingDenormalized" (id, uid, "eventTypeId", title, description, "startTime", "endTime", "createdAt", "updatedAt", location, paid,
    status, rescheduled, "userId", "teamId", "eventLength", "eventParentId", "userEmail", "userName", "userUsername",
    "ratingFeedback", rating, "noShowHost", "isTeamBooking")
  SELECT b.id, b.uid, b."eventTypeId", b.title, b.description, b."startTime", b."endTime", b."createdAt",
    b."updatedAt", b.location, b.paid, b.status, b.rescheduled, b."userId", et."teamId", et.length, et."parentId",
    u.email, u.name, u.username, b."ratingFeedback", b.rating, b."noShowHost",
    CASE WHEN et."teamId" IS NOT NULL THEN 1 ELSE 0 END
  FROM "Booking" b
  INNER JOIN inserted i ON i.id = b.id
  LEFT JOIN "EventType" et ON b."eventTypeId" = et.id
  LEFT JOIN "users" u ON u.id = b."userId";
END');
EXEC(N'CREATE OR ALTER TRIGGER [dbo].[booking_denorm_booking_delete_trigger] ON [dbo].[Booking] AFTER DELETE AS
BEGIN
  SET NOCOUNT ON;
  DELETE bd FROM "BookingDenormalized" bd INNER JOIN deleted d ON d.id = bd.id;
END');
EXEC(N'CREATE OR ALTER TRIGGER [dbo].[booking_denorm_event_type_team_id_update_trigger] ON [dbo].[EventType] AFTER UPDATE AS
BEGIN
  SET NOCOUNT ON;
  IF NOT UPDATE("teamId") RETURN;
  UPDATE bd SET "teamId" = i."teamId", "isTeamBooking" = CASE WHEN i."teamId" IS NOT NULL THEN 1 ELSE 0 END
  FROM "BookingDenormalized" bd INNER JOIN inserted i ON bd."eventTypeId" = i.id;
END');
EXEC(N'CREATE OR ALTER TRIGGER [dbo].[booking_denorm_event_type_length_update_trigger] ON [dbo].[EventType] AFTER UPDATE AS
BEGIN
  SET NOCOUNT ON;
  IF NOT UPDATE(length) RETURN;
  UPDATE bd SET "eventLength" = i.length
  FROM "BookingDenormalized" bd INNER JOIN inserted i ON bd."eventTypeId" = i.id;
END');
EXEC(N'CREATE OR ALTER TRIGGER [dbo].[booking_denorm_event_type_parent_id_update_trigger] ON [dbo].[EventType] AFTER UPDATE AS
BEGIN
  SET NOCOUNT ON;
  IF NOT UPDATE("parentId") RETURN;
  UPDATE bd SET "eventParentId" = i."parentId"
  FROM "BookingDenormalized" bd INNER JOIN inserted i ON bd."eventTypeId" = i.id;
END');
EXEC(N'CREATE OR ALTER TRIGGER [dbo].[booking_denorm_user_update_trigger] ON [dbo].[users] AFTER UPDATE AS
BEGIN
  SET NOCOUNT ON;
  IF NOT (UPDATE(email) OR UPDATE(name) OR UPDATE(username)) RETURN;
  UPDATE bd SET "userEmail" = i.email, "userName" = i.name, "userUsername" = i.username
  FROM "BookingDenormalized" bd INNER JOIN inserted i ON bd."userId" = i.id;
END');
-- bookings that existed before these triggers
INSERT INTO "BookingDenormalized" (id, uid, "eventTypeId", title, description, "startTime", "endTime", "createdAt", "updatedAt", location, paid,
    status, rescheduled, "userId", "teamId", "eventLength", "eventParentId", "userEmail", "userName", "userUsername",
    "ratingFeedback", rating, "noShowHost", "isTeamBooking")
  SELECT b.id, b.uid, b."eventTypeId", b.title, b.description, b."startTime", b."endTime", b."createdAt",
    b."updatedAt", b.location, b.paid, b.status, b.rescheduled, b."userId", et."teamId", et.length, et."parentId",
    u.email, u.name, u.username, b."ratingFeedback", b.rating, b."noShowHost",
    CASE WHEN et."teamId" IS NOT NULL THEN 1 ELSE 0 END
  FROM "Booking" b
  
  LEFT JOIN "EventType" et ON b."eventTypeId" = et.id
  LEFT JOIN "users" u ON u.id = b."userId"
  WHERE NOT EXISTS (SELECT 1 FROM "BookingDenormalized" bd WHERE bd.id = b.id);

-- Membership: the system role that matches the membership role
EXEC(N'CREATE OR ALTER TRIGGER [dbo].[membership_role_change_trigger] ON [dbo].[Membership] AFTER INSERT, UPDATE AS
BEGIN
  SET NOCOUNT ON;
  IF EXISTS (SELECT 1 FROM deleted) AND NOT UPDATE(role) RETURN;
  UPDATE m SET "customRoleId" = CASE i.role
      WHEN ''OWNER'' THEN ''owner_role''
      WHEN ''ADMIN'' THEN ''admin_role''
      WHEN ''MEMBER'' THEN ''member_role''
      ELSE m."customRoleId"
    END
  FROM "Membership" m INNER JOIN inserted i ON i.id = m.id;
END');

-- Insights views
EXEC(N'CREATE OR ALTER VIEW [dbo].[BookingTimeStatus] AS
SELECT b.id, b.uid, b."eventTypeId", b.title, b.description, b."startTime", b."endTime", b."createdAt", b.location,
    b.paid, b.status, b.rescheduled, b."userId", et."teamId", et.length AS "eventLength",
    CASE
      WHEN b.rescheduled = 1 THEN ''rescheduled''
      WHEN b.status = ''CANCELLED'' AND b.rescheduled IS NULL THEN ''cancelled''
      WHEN b."endTime" < SYSUTCDATETIME() THEN ''completed''
      WHEN b."endTime" > SYSUTCDATETIME() THEN ''uncompleted''
      ELSE NULL
    END AS "timeStatus",
    et."parentId" AS "eventParentId", u.email AS "userEmail", u.username, b."ratingFeedback", b.rating,
    b."noShowHost", CAST(CASE WHEN et."teamId" IS NOT NULL THEN 1 ELSE 0 END AS bit) AS "isTeamBooking"
  FROM "Booking" b
  LEFT JOIN "EventType" et ON b."eventTypeId" = et.id
  LEFT JOIN "users" u ON u.id = b."userId"');
EXEC(N'CREATE OR ALTER VIEW [dbo].[BookingTimeStatusDenormalized] AS
SELECT id, uid, "eventTypeId", title, description, "startTime", "endTime", "createdAt", "updatedAt", location, paid,
    status, rescheduled, "userId", "teamId", "eventLength", "eventParentId", "userEmail", "userName", "userUsername",
    "ratingFeedback", rating, "noShowHost", "isTeamBooking",
    CASE
      WHEN rescheduled = 1 THEN ''rescheduled''
      WHEN status = ''CANCELLED'' AND rescheduled IS NULL THEN ''cancelled''
      WHEN "endTime" < SYSUTCDATETIME() THEN ''completed''
      WHEN "endTime" > SYSUTCDATETIME() THEN ''uncompleted''
      ELSE NULL
    END AS "timeStatus"
  FROM "BookingDenormalized"');

